#include <bits/stdc++.h>
using namespace std;

// A vizinhança de uma cidade em uma reta (Voronoi 1D) é limitada:
//  - cidade mais à esquerda: de 0 até o ponto médio com a segunda cidade
//      comprimento = (X[0] + X[1]) / 2
//  - cidade mais à direita: do ponto médio com a penúltima cidade até T
//      comprimento = T - (X[N-2] + X[N-1]) / 2
//  - cidade intermediária: entre os pontos médios com vizinhos adjacentes
//      comprimento = (X[i+1] - X[i-1]) / 2
// Trabalhamos com o dobro dos valores (inteiros) para evitar erros de ponto flutuante.

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long T;
    int N;
    cin >> T >> N;

    vector<long long> x(N);
    for (int i = 0; i < N; i++) cin >> x[i];

    sort(x.begin(), x.end());

    long long best; // dobro da menor vizinhança
    best = min(x[0] + x[1],                 // cidade mais à esquerda
               2 * T - x[N - 2] - x[N - 1]); // cidade mais à direita

    for (int i = 1; i + 1 < N; i++)
        best = min(best, x[i + 1] - x[i - 1]); // cidades intermediárias

    cout << fixed << setprecision(2) << best / 2.0 << "\n";
    return 0;
}
